        base_shapes = {
            "tetrahedron": self.define_polygon(3),
            "cube": self.define_polygon(4),
            "octahedron": self.define_polygon(8),
            "dodecahedron": self.define_polygon(12),
            "icosahedron": self.define_polygon(20),
        }
